// The Arabic catalogue, in its own module.
//
// # Why this is not in `strings.ts`
//
// A bundler splits by MODULE, never by export. While `ar` and `bn` lived in
// `strings.ts` beside `en`, every front end that imported `en` -- which is
// every one of them, on the first frame -- pulled all three catalogues into
// its main chunk. `web-next` already asked for the other two with a dynamic
// `import()`, and it did nothing: the specifier named the module that was
// already loaded, so the request resolved against the main chunk and the split
// the code was written to make never happened.
//
// Measured in the production build before this file existed: one chunk of
// 1.77 MB containing English, Arabic and Bangla together, requested by every
// route including the sign-in page. Two thirds of it is a language the person
// signing in has not chosen and, for most shops, never will.
//
// So the rule is a file boundary, not a comment: anything a locale switch
// loads on demand has to be reachable ONLY through a dynamic import, and that
// means it has to live somewhere `strings.ts` does not import.
//
// `catalogues.ts` is what needs all three at once. Importing THAT is what
// costs the megabyte, and only the frozen `web/` provider does.

import type { Key } from './strings';

/**
 * The Arabic catalogue.
 *
 * `Record<Key, string>` rather than a partial: a key added to `en` without an
 * Arabic string is a compile error, not a screen that silently falls back to
 * English on a Saudi shop's till.
 *
 * Retail and accounting terms use the wording ZATCA's own Arabic materials use
 * where they have one — فاتورة ضريبية for tax invoice, ضريبة القيمة المضافة for
 * VAT — because a shop reading our screen and reading a ZATCA notice should see
 * the same words. Terms with no official Arabic source are ordinary usage and
 * are listed in the audit as wanting a native reviewer before release.
 */
