  /* Prose that was written straight into the components.
   *
   * Empty-state bodies, screen subtitles, and the aria-labels on the numeric
   * inputs of a purchase order -- forty-one sentences that a source scan found
   * and no catalogue had ever seen. They rendered in English on an Arabic
   * screen and on a Bangla one, and the aria-labels did it to a screen reader,
   * who is the one reader with nothing else to go on. */

