  'nx.plat.ruBlockedAfter': 'بعد التسجيل ووضع علامة التحقق: يُفتح السوق للعملاء الجدد، وتُحلّ القيمة بتاريخ كل مستند يُعالج، ويحلّ التصحيح محل السابق دون محوه — فإعادة تشغيل شهر سابق تعطي إجابة ذلك الشهر.',
