  'nx.plat.ruAwaitingProduction': 'أي نشر إنتاجي يخدم هذا السوق يقلع كالمعتاد رغم أن هذه القيمة غير مُتحقَّقة. الناقص رقم منشور في مكان آخر، لا جزء من هذا المنتج: البرنامج الذي يحسب به مبنيّ ومختبَر، ويرفض باسمه حتى يُسجّل الرقم.',
  'nx.plat.ruNotDescribed': 'لا يحتفظ هذا المنتج بوصف لمصدر هذه الأرقام، لذا تُسجّل كحمولة بدل حقول موسومة.',
